record.field:
config = contract.pt_state_id
if not config:
    result = 0.0
elif config.periodicity == 'monthly':
    wage = categories.GROSS
    slabs = config.slab_line_ids.filtered(lambda l: l.lower_bound <= wage and (not l.upper_bound or wage <= l.upper_bound))
    if not slabs:
        result = 0.0
    else:
        slab = slabs[0]
        if slab.topup_month and int(slab.topup_month) == payslip.date_to.month:
            result = slab.topup_amount
        else:
            result = slab.amount
else:
    month = payslip.date_to.month
    year = payslip.date_to.year
    if month in (4, 5, 6, 7, 8, 9):
        period_start = payslip.date_to.replace(month=4, day=1)
        charge_month = config.charge_month_h1
    elif month in (10, 11, 12):
        period_start = payslip.date_to.replace(month=10, day=1)
        charge_month = config.charge_month_h2
    else:
        period_start = payslip.date_to.replace(year=year - 1, month=10, day=1)
        charge_month = config.charge_month_h2
    if charge_month and int(charge_month) == month:
        payslip.env.flush_all()
        hy_gross = payslips.sum('GROSS', period_start, payslip.date_to) + categories.GROSS
        slabs = config.slab_line_ids.filtered(lambda l: l.lower_bound <= hy_gross and (not l.upper_bound or hy_gross <= l.upper_bound))
        result = slabs[0].amount if slabs else 0.0
    else:
        result = 0.0
